CREATE VIEW v43474 AS SELECT MBRTOUCHES(ST_GEOMFROMTEXT('GEOMETRYCOLLECTION(LINESTRING(5 0,5 10),GEOMETRYCOLLECTION())'), ST_GEOMFROMTEXT('LINESTRING(5 0,5 10)')), ST_ASTEXT(ST_INTERSECTION(ST_GEOMFROMTEXT('POLYGON((0 0, 50 45, 40 50, 0 0))'), ST_GEOMFROMTEXT('LINESTRING(-10 -10, 200 200, 199 201, -11 -9)'))), ST_ASTEXT(ST_CONVEXHULL(ST_GEOMFROMTEXT('POINT(0 -0)'))), SUM(x6.v43212), SUM(DISTINCT (TRUNCATE((0.1), NULL))) FROM v43211 AS x6 GROUP BY x6.v43213 WITH ROLLUP